  const right = upper ? n <= 8 : n >= 25;
  const [h, rl] = DIMS[upper ? "U" : "L"][p - 1];
  return { n, upper, p, right, kind: KINDS[p - 1], h, rl, anterior: p <= 3, name: `${upper ? "Upper" : "Lower"} ${right ? "right" : "left"} ${POS_NAME[p - 1]}` };
