const quadPos = (n) => (n <= 8 ? n : n <= 16 ? 17 - n : n <= 24 ? n - 16 : 33 - n);
const shapeOf = (n) => { const p = quadPos(n); return p <= 3 ? "molar" : p <= 5 ? "premolar" : p === 6 ? "canine" : "incisor"; };
