  const cap = crownCap(v, view, upper, shape);
  const filterFor = (fid, color, paths) => `<filter id="${fid}" filterUnits="userSpaceOnUse" x="${f2(vp.x - 8)}" y="${f2(vp.y - 8)}" width="${f2(vp.w + 16)}" height="${f2(vp.h + 16)}" color-interpolation-filters="sRGB"><feMorphology in="SourceAlpha" operator="dilate" radius="1.15" result="closed"/><feMorphology in="closed" operator="erode" radius="2" result="inner"/><feComposite in="closed" in2="inner" operator="out" result="ring"/><feFlood flood-color="${color}"/><feComposite in2="ring" operator="in"/></filter><g ${clip}><g filter="url(#${fid})">${paths.map((d) => `<path d="${d}" fill="#000"/>`).join("")}</g></g>`;
